    readonly Cooldown cooldown = new Cooldown(2f);
    void Update() => cooldown.Tick(Time.deltaTime);
    [ContextMenu("Try use")]
    void TryUse() => Debug.Log(cooldown.TryUse() ? "Used" : "Cooling", this);
}
public sealed class Cooldown
{
    readonly float duration;
    float remaining;
    public Cooldown(float duration) { this.duration = Mathf.Max(0f, duration); }
    public void Tick(float dt) { remaining = Mathf.Max(0f, remaining - Mathf.Max(0f, dt)); }
    public bool TryUse()
    {
        if (remaining > 0f) return false;
        remaining = duration;
        return true;
    }
}

