using UnityEngine;
public sealed class PeriodicProbe : MonoBehaviour
{
    [SerializeField, Min(0.01f)] float period = 1f;
    [SerializeField, Min(1)] int maxPerFrame = 4;
    double accumulated;
    void Update()
    {
        double safePeriod = Mathf.Max(0.01f, period);
        accumulated += Time.deltaTime;
        int count = 0;
        while (accumulated >= safePeriod && count < Mathf.Max(1, maxPerFrame))
        {
            accumulated -= safePeriod;
            count++;
            Debug.Log("Period elapsed", this);
        }
        if (accumulated >= safePeriod) accumulated %= safePeriod;
    }
}

using UnityEngine;
public sealed class InterpolationProbe : MonoBehaviour
{
    const float Step = 0.1f;
    Vector3 previous, current;
    float accumulator;
    void Awake() => previous = current = transform.position;
    void Update()
    {
        accumulator += Time.deltaTime;
        int steps = 0;
        while (accumulator >= Step && steps < 8)
        {
            previous = current;
            current += Vector3.right * Step;
            accumulator -= Step;
            steps++;
        }
        if (accumulator >= Step) accumulator %= Step;
        transform.position = Vector3.Lerp(previous, current, accumulator / Step);
    }
}

