public sealed class BindingOverrideProbe : MonoBehaviour
{
    const string Key = "learning.fire.singleBindingPath.v2";
    InputAction fire;
    void Awake()
    {
        fire = new InputAction("Fire", InputActionType.Button, "<Keyboard>/space");
        try
        {
            if (PlayerPrefs.HasKey(Key))
                fire.ApplyBindingOverride(0, PlayerPrefs.GetString(Key));
        }
        catch (Exception error) { Debug.LogWarning(error.Message, this); }
    }
    void OnEnable() => fire.Enable();
    void OnDisable() => fire.Disable();
    void Update() { if (fire.WasPressedThisFrame()) Debug.Log("Fire", this); }
    [ContextMenu("Use Enter")]
    void Rebind()
    {
        fire.ApplyBindingOverride(0, "<Keyboard>/enter");
        PlayerPrefs.SetString(Key, fire.bindings[0].overridePath);
        PlayerPrefs.Save();
    }
    [ContextMenu("Restore default")]
    void Restore()
    {
        fire.RemoveAllBindingOverrides();
        PlayerPrefs.DeleteKey(Key);
        PlayerPrefs.Save();
    }
    void OnDestroy() => fire.Dispose();
}

using UnityEngine;
using UnityEngine.InputSystem;
public sealed class BufferedCommandProbe : MonoBehaviour
{
    [SerializeField] bool canConsume = true;
    [SerializeField, Min(0f)] float bufferSeconds = 0.15f;
    InputAction jump;
    bool pending;
    double expires;
    void Awake() => jump = new InputAction("Jump", InputActionType.Button, "<Keyboard>/space");
    void OnEnable() => jump.Enable();
    void Update()
    {
        if (!jump.WasPressedThisFrame()) return;
        pending = true;
        expires = Time.timeAsDouble + bufferSeconds;
    }
    void FixedUpdate()
    {
        if (!pending) return;
        if (Time.timeAsDouble > expires) { pending = false; return; }
        if (!canConsume) return;
        pending = false;
        Debug.Log("Consumed exactly once.", this);
    }
    void OnDisable() { jump.Disable(); pending = false; }
    void OnDestroy() => jump.Dispose();
}

