using UnityEngine;
[RequireComponent(typeof(Rigidbody), typeof(CapsuleCollider))]
public sealed class SimpleGroundMotor : MonoBehaviour
{
    [SerializeField] Transform groundPoint;
    [SerializeField] LayerMask groundLayers;
    [SerializeField, Min(0f)] float speed = 5f;
    [SerializeField, Min(0f)] float jumpSpeed = 5f;
    Rigidbody body;
    Vector2 move;
    bool jumpPending;
    double expires;
    void Awake() => body = GetComponent<Rigidbody>();
    public void SetMove(Vector2 value) => move = Vector2.ClampMagnitude(value, 1f);
    public void RequestJump()
    {
        jumpPending = true;
        expires = Time.timeAsDouble + 0.15;
    }
    void FixedUpdate()
    {
        if (groundPoint == null) return;
        Vector3 velocity = body.linearVelocity;
        velocity.x = move.x * speed;
        velocity.z = move.y * speed;
        if (jumpPending && Time.timeAsDouble > expires) jumpPending = false;
        bool grounded = Physics.CheckSphere(groundPoint.position, 0.12f,
            groundLayers, QueryTriggerInteraction.Ignore);
        if (jumpPending && grounded)
        {
            jumpPending = false;
            velocity.y = jumpSpeed;
        }
        body.linearVelocity = velocity;
    }
    void OnDisable() { move = Vector2.zero; jumpPending = false; }
}

