public class OneShotParticlePool : MonoBehaviour
{
    [SerializeField] ParticleSystem prefab;
    [SerializeField, Min(1)] int maxActive = 12;
    ObjectPool<ParticleSystem> pool;
    readonly List<ParticleSystem> active = new List<ParticleSystem>();
    void Awake()
    {
        if (!prefab) { enabled = false; return; }
        pool = new ObjectPool<ParticleSystem>(
            () => Instantiate(prefab, transform),
            p => p.gameObject.SetActive(true),
            p => { p.Stop(true, ParticleSystemStopBehavior.StopEmittingAndClear); p.gameObject.SetActive(false); },
            p => Destroy(p.gameObject), true, 4, 16);
    }
    public void Emit(Vector3 position)
    {
        if (!isActiveAndEnabled || pool == null || active.Count >= maxActive) return;
        var p = pool.Get();
        p.transform.position = position;
        p.Play(true);
        active.Add(p);
    }
    void Update()
    {
        for (int i = active.Count - 1; i >= 0; i--)
            if (!active[i].IsAlive(true)) { pool.Release(active[i]); active.RemoveAt(i); }
    }
    void OnDisable()
    {
        if (pool == null) return;
        foreach (var p in active) pool.Release(p);
        active.Clear();
    }
