    private readonly List<GameObject> active = new List<GameObject>();
    private void Awake()
    {
        pool = new ObjectPool<GameObject>(
            createFunc: CreateItem,
            actionOnGet: item => { item.transform.position = Vector3.zero; item.SetActive(true); },
            actionOnRelease: item => item.SetActive(false),
            actionOnDestroy: item => Destroy(item),
            collectionCheck: true, defaultCapacity: 4, maxSize: 4);
    }
    private GameObject CreateItem()
    {
        var item = GameObject.CreatePrimitive(PrimitiveType.Cube);
        item.transform.SetParent(transform);
        item.SetActive(false);
        return item;
    }
    [ContextMenu("Rent One")]
    private void RentOne()
    {
        if (!Application.isPlaying || pool == null) return;
        active.Add(pool.Get());
        Report();
    }
    [ContextMenu("Return One")]
    private void ReturnOne()
    {
        if (!Application.isPlaying || active.Count == 0) return;
        int last = active.Count - 1;
        GameObject item = active[last];
        active.RemoveAt(last);
        pool.Release(item);
        Report();
    }
    private void Report() => Debug.Log($"active={pool.CountActive}, idle={pool.CountInactive}");
    private void OnDestroy()
    {
        foreach (GameObject item in active) if (item != null) Destroy(item);
        active.Clear();
        pool?.Clear();
    }
}

