        Debug.Log($"Request accepted: {accepted}; completion must be checked later.", this);
    }
}

using Unity.Collections;
using Unity.Jobs;
using UnityEngine;

public sealed class JobOwnershipProbe : MonoBehaviour
{
    private struct DoubleJob : IJob
    {
        public NativeArray<int> Values;
        public void Execute()
        {
            for (int i = 0; i < Values.Length; i++) Values[i] *= 2;
        }
    }
    [ContextMenu("Run Job Lab")]
    private void Run()
    {
        var values = new NativeArray<int>(4, Allocator.TempJob);
        JobHandle handle = default;
        try
        {
            for (int i = 0; i < values.Length; i++) values[i] = i + 1;
            handle = new DoubleJob { Values = values }.Schedule();
            handle.Complete();
            Debug.Log($"First={values[0]}, Last={values[3]}", this);
        }
        finally { handle.Complete(); if (values.IsCreated) values.Dispose(); }
    }
}

using Unity.Burst;
