using System.IO;
using System.Linq;
using UnityEditor;
using UnityEditor.Build.Reporting;
using UnityEngine;

public static class BuildWindowsLab
{
    [MenuItem("Engine Lab/Build Windows Development")]
    public static void Build()
    {
        string[] scenes = EditorBuildSettings.scenes.Where(s => s.enabled).Select(s => s.path).ToArray();
        if (scenes.Length == 0) throw new System.InvalidOperationException("No enabled scenes");
        const string folder = "Builds/EngineLabWindows";
        Directory.CreateDirectory(folder);
        var options = new BuildPlayerOptions {
            scenes = scenes,
            locationPathName = folder + "/EngineLab.exe",
            target = BuildTarget.StandaloneWindows64,
            options = BuildOptions.Development
        };
        BuildReport report = BuildPipeline.BuildPlayer(options);
        Debug.Log($"Result={report.summary.result}, Size={report.summary.totalSize}");
        if (report.summary.result != BuildResult.Succeeded)
            throw new System.InvalidOperationException("Build failed; inspect full build log");
    }
}

